'use strict';
const $=id=>document.getElementById(id),KEY='studyflow.tasks.v1';
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const offset=n=>{const d=new Date();d.setDate(d.getDate()+n);return localDate(d)};
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(new Date(`${s}T00:00:00`).getTime())&&localDate(new Date(`${s}T00:00:00`))===s;
const validTask=t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&t.title.trim().length>0&&t.title.length<=100&&typeof t.course==='string'&&t.course.length<=40&&validDate(t.due)&&['high','medium','low'].includes(t.priority)&&typeof t.notes==='string'&&t.notes.length<=1000&&typeof t.done==='boolean'&&Number.isFinite(t.created);
const seeds=()=>[{title:'바이브 코딩 중간 프로젝트 완성',course:'앱 개발',due:offset(2),priority:'high',notes:'앱 시연을 준비하고 README와 Todo 변경 기록을 정리해요.',done:false},{title:'3장 수업 노트 정리',course:'디자인 기초',due:offset(0),priority:'medium',notes:'핵심 개념을 나만의 언어로 정리해요.',done:false},{title:'사용자 연구 사례 읽기',course:'인터랙션 디자인',due:offset(4),priority:'low',notes:'',done:false},{title:'1주 차 학습 계획 제출',course:'자기 주도 학습',due:offset(-1),priority:'medium',notes:'',done:true}].map((t,i)=>({...t,id:crypto.randomUUID(),created:Date.now()-i}));
let tasks=[],storageIssue=false;
try{const raw=localStorage.getItem(KEY);if(raw===null){tasks=seeds();localStorage.setItem(KEY,JSON.stringify(tasks))}else{const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||!parsed.every(validTask))throw Error();tasks=parsed}}catch{storageIssue=true;tasks=[]}
// Translate only untouched bundled examples; user-written tasks are preserved.
const legacyExamples=[["\u5b8c\u6210 Vibe Coding \u671f\u4e2d\u9879\u76ee","\u5e94\u7528\u5f00\u53d1","\u5b8c\u6210\u5e94\u7528\u6f14\u793a\uff0c\u6574\u7406 README \u548c Todo \u53d8\u66f4\u8bb0\u5f55\u3002","\ubc14\uc774\ube0c \ucf54\ub529 \uc911\uac04 \ud504\ub85c\uc81d\ud2b8 \uc644\uc131","\uc571 \uac1c\ubc1c","\uc571 \uc2dc\uc5f0\uc744 \uc900\ube44\ud558\uace0 README\uc640 Todo \ubcc0\uacbd \uae30\ub85d\uc744 \uc815\ub9ac\ud574\uc694."],["\u6574\u7406\u7b2c\u4e09\u7ae0\u8bfe\u5802\u7b14\u8bb0","\u8bbe\u8ba1\u57fa\u7840","\u628a\u91cd\u70b9\u6982\u5ff5\u6574\u7406\u6210\u81ea\u5df1\u7684\u8bed\u8a00\u3002","3\uc7a5 \uc218\uc5c5 \ub178\ud2b8 \uc815\ub9ac","\ub514\uc790\uc778 \uae30\ucd08","\ud575\uc2ec \uac1c\ub150\uc744 \ub098\ub9cc\uc758 \uc5b8\uc5b4\ub85c \uc815\ub9ac\ud574\uc694."],["\u9605\u8bfb\u7528\u6237\u7814\u7a76\u6848\u4f8b","\u4ea4\u4e92\u8bbe\u8ba1","","\uc0ac\uc6a9\uc790 \uc5f0\uad6c \uc0ac\ub840 \uc77d\uae30","\uc778\ud130\ub799\uc158 \ub514\uc790\uc778",""],["\u63d0\u4ea4\u7b2c\u4e00\u5468\u5b66\u4e60\u8ba1\u5212","\u81ea\u4e3b\u5b66\u4e60","","1\uc8fc \ucc28 \ud559\uc2b5 \uacc4\ud68d \uc81c\ucd9c","\uc790\uae30 \uc8fc\ub3c4 \ud559\uc2b5",""]];
let migrated=false;for(const task of tasks){const example=legacyExamples.find(x=>task.title===x[0]&&task.course===x[1]&&task.notes===x[2]);if(example){[task.title,task.course,task.notes]=example.slice(3);migrated=true}}if(migrated){try{localStorage.setItem(KEY,JSON.stringify(tasks))}catch{storageIssue=true}}
let view='all',filter='all',editing=null,deleting=null,toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks));return true}catch{toast('브라우저 저장에 실패했어요. 먼저 백업을 내보내 주세요.');return false}}
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function render(){const today=localDate(),done=tasks.filter(t=>t.done).length,pending=tasks.length-done,overdue=tasks.filter(t=>!t.done&&t.due<today).length,pct=tasks.length?Math.round(done/tasks.length*100):0;
 $('date').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'long'});$('total').textContent=tasks.length;$('pending').textContent=pending;$('completed').textContent=done;$('nav-count').textContent=tasks.length;$('overdue').textContent=overdue?`기한이 지난 할 일 ${overdue}개`:'기한이 지난 할 일이 없어요';$('percent').replaceChildren(document.createTextNode(String(pct)),el('span','', '%'));$('bar').style.width=`${pct}%`;$('progress-text').textContent=tasks.length?`전체 ${tasks.length}개 중 ${done}개 완료`:'첫 번째 할 일을 시작해 보세요';
 const query=$('search').value.trim().toLowerCase();let rows=tasks.filter(t=>(view!=='today'||t.due===today)&&(view!=='done'||t.done)&&(filter!=='pending'||!t.done)&&(filter!=='done'||t.done)&&`${t.title} ${t.course}`.toLowerCase().includes(query));
 const weights={high:0,medium:1,low:2};rows.sort((a,b)=>Number(a.done)-Number(b.done)||($('sort').value==='new'?b.created-a.created:$('sort').value==='priority'?weights[a.priority]-weights[b.priority]||a.due.localeCompare(b.due):a.due.localeCompare(b.due)||weights[a.priority]-weights[b.priority]));
 $('view-title').replaceChildren(document.createTextNode(view==='today'?'오늘 마감 ':view==='done'?'완료한 할 일 ':'나의 할 일 '),el('span','',String(rows.length)));$('result-count').textContent=`${rows.length}개 표시 · 전체 ${tasks.length}개`;
 const list=$('task-list');list.replaceChildren();if(!rows.length){const empty=el('div','empty');empty.append(el('b','',query?'검색 결과가 없어요':'아직 할 일이 없어요'),el('span','',query?'다른 검색어를 입력하거나 필터를 바꿔 보세요.':'「할 일 추가」를 눌러 다음 한 걸음을 계획해 보세요.'));list.append(empty)}
 for(const t of rows){const row=el('article',`task${t.done?' done':''}`),check=el('button','check',t.done?'✓':'');check.setAttribute('aria-label',`${t.done?'완료 취소':'완료'}: ${t.title}`);check.setAttribute('aria-pressed',String(t.done));check.onclick=()=>{t.done=!t.done;const saved=save();render();if(saved)toast(t.done?'한 걸음 더 완료했어요. 잘했어요!':'할 일을 진행 중으로 변경했어요')};const content=el('div','task-content'),meta=el('div','task-meta');content.append(el('div','task-title',t.title));if(t.course)meta.append(el('span','course',t.course));const dueLabel=t.due===today?'오늘 마감':`${Number(t.due.slice(5,7))}월 ${Number(t.due.slice(8,10))}일 마감`;meta.append(el('span',`due ${!t.done&&t.due<today?'over':!t.done&&t.due===today?'soon':''}`,`◷ ${dueLabel}${!t.done&&t.due<today?' · 기한 지남':''}`),el('span',`badge ${t.priority}`,{high:'높음',medium:'보통',low:'낮음'}[t.priority]));content.append(meta);if(t.notes)content.append(el('div','task-notes',t.notes));const actions=el('div','task-actions'),edit=el('button','icon','✎'),del=el('button','icon','×');edit.setAttribute('aria-label',`수정: ${t.title}`);del.setAttribute('aria-label',`삭제: ${t.title}`);edit.onclick=()=>openEditor(t);del.onclick=()=>{deleting=t.id;$('delete-dialog').showModal()};actions.append(edit,del);row.append(check,content,actions);list.append(row)}
}
function openEditor(t){editing=t?.id??null;$('task-form').reset();$('dialog-title').textContent=t?'학습 할 일 수정':'새 학습 할 일';for(const field of ['title','course','due','priority','notes'])$(field).value=t?t[field]:field==='due'?offset(1):field==='priority'?'medium':'';$('editor').showModal();$('title').focus()}
$('add').onclick=()=>openEditor();for(const id of ['close','cancel'])$(id).onclick=()=>$('editor').close();$('task-form').onsubmit=e=>{e.preventDefault();const title=$('title').value.trim();if(!title){$('title').setCustomValidity('할 일 이름을 입력해 주세요');$('title').reportValidity();return}if(!validDate($('due').value)){toast('올바른 날짜를 선택해 주세요');return}const changes={title,course:$('course').value.trim(),due:$('due').value,priority:$('priority').value,notes:$('notes').value.trim()};if(editing){Object.assign(tasks.find(t=>t.id===editing),changes)}else tasks.push({...changes,id:crypto.randomUUID(),created:Date.now(),done:false});const saved=save();$('editor').close();render();if(saved)toast(editing?'할 일을 수정했어요':'새 할 일을 추가했어요')};$('title').oninput=()=>$('title').setCustomValidity('');
$('delete-cancel').onclick=()=>$('delete-dialog').close();$('delete-confirm').onclick=()=>{tasks=tasks.filter(t=>t.id!==deleting);const saved=save();$('delete-dialog').close();render();if(saved)toast('할 일을 삭제했어요')};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter='all';document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n.dataset.filter==='all'));render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n===b));render()});$('search').oninput=render;$('sort').onchange=render;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),tasks},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=`studyflow-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업을 내보냈어요')};$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.tasks)||!data.tasks.every(validTask))throw Error();const ids=new Set(tasks.map(t=>t.id));let count=0;for(const t of data.tasks)if(!ids.has(t.id)){tasks.push(t);ids.add(t.id);count++}const saved=save();render();if(saved)toast(`${count}개를 추가했어요. 기존 할 일은 유지돼요.`)}catch{toast('가져올 수 없어요. 올바른 StudyFlow JSON 백업을 선택해 주세요.')}finally{e.target.value=''}};
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue??'[]');if(Array.isArray(next)&&next.every(validTask)){tasks=next;render()}}catch{}}});render();if(storageIssue)toast('저장된 데이터를 읽을 수 없어요. 브라우저 저장소를 확인하거나 백업을 가져와 주세요.');else if(tasks.length===4&&tasks.every(t=>t.created>Date.now()-10000))toast('예시 할 일 4개를 준비했어요. 자유롭게 수정하거나 삭제해 보세요.');setInterval(render,60000);
